{"file_path":"src/values.js","content":"// Value model helpers shared by the parser and the printers.

// Tables (from headers, dotted-key creation, or inline-table literals) are
// plain JS objects. We keep a side table of metadata (whether a `[name]`
// header has already made a table "current") so the metadata never shows up
// as an enumerable JSON member.
export const tableMeta = new WeakMap()

// Arrays created by `[[name]]` headers are tagged so we know they are arrays
// of tables (as opposed to a plain value array written as `a = [ ... ]`).
export const aotSet = new WeakSet()

export function newTable() {
  const t = {}
  tableMeta.set(t, { headerDefined: false })
  return t
}

export function isTable(v) {
  return v !== null && typeof v === 'object' && !Array.isArray(v) && !(v instanceof TFloat)
}

// Wraps a float value so we can tell it apart from an integer even when its
// numeric value happens to be whole.
export class TFloat {
  constructor(value) {
    this.value = value
  }
}

export function typeOf(value) {
  if (Array.isArray(value)) return 'array'
  if (value instanceof TFloat) return 'float'
  if (typeof value === 'number') return 'integer'
  if (typeof value === 'boolean') return 'boolean'
  if (typeof value === 'string') return 'string'
  if (isTable(value)) return 'table'
  throw new Error('unknown value type')
}
"}

