chunk.argumentsDelta:
{"file_path":"src/print.js","content":"import { TFloat, isTable, typeOf } from './values.js'

function indentStr(n) {
  return '  '.repeat(n)
}

function stringifyValue(value, indent) {
  if (typeof value === 'boolean') return value ? 'true' : 'false'
  if (typeof value === 'number') return JSON.stringify(value)
  if (value instanceof TFloat) return JSON.stringify(value.value)
  if (typeof value === 'string') return JSON.stringify(value)
  if (Array.isArray(value)) return stringifyArray(value, indent)
  if (isTable(value)) return stringifyObject(value, indent)
  throw new Error('unknown value type')
}

function stringifyArray(arr, indent) {
  if (arr.length === 0) return '[]'
  const inner = indentStr(indent + 1)
  const items = arr.map((v) => inner + stringifyValue(v, indent + 1))
  return '[\n' + items.join(',\n') + '\n' + indentStr(indent) + ']'
}

function stringifyObject(obj, indent) {
  const keys = Object.keys(obj).sort()
  if (keys.length === 0) return '{}'
  const inner = indentStr(indent + 1)
  const items = keys.map((k) => inner + JSON.stringify(k) + ': ' + stringifyValue(obj[k], indent + 1))
  return '{\n' + items.join(',\n') + '\n' + indentStr(indent) + '}'
}

export function printJson(root) {
  return stringifyValue(root, 0) + '\n'
}

function collect(node, path, out) {
  if (Array.isArray(node)) {
    node.forEach((child, idx) => {
      const p = `${path}[${idx}]`
      out.push(`${p} ${typeOf(child)}`)
      collect(child, p, out)
    })
  } else if (isTable(node)) {
    for (const k of Object.keys(node).sort()) {
      const child = node[k]
      const p = path === '' ? k : `${path}.${k}`
      out.push(`${p} ${typeOf(child)}`)
      collect(child, p, out)
    }
  }
}

export function printKeys(root) {
  const out = []
  collect(root, '', out)
  return out.length ? out.join('\n') + '\n' : ''
}
"}

