    while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
    if (i >= line.length) continue // blank
    const c = line[i]
    if (c === '#' || c === ';') continue // comment-only
    const p = new LineParser(line, i, lineNo)
