export class ParseError extends Error {
  constructor(line, reason) {
    super(reason)
    this.line = line
    this.reason = reason
  }
}

function err(line, reason) {
  throw new ParseError(line, reason)
}

const NAME_RE = /^[A-Za-z0-9_-]+/
const DIGITS = '[0-9]+(?:_[0-9]+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(
  `^[+-]?${DIGITS}(?:(?:\\.${DIGITS})(?:[eE][+-]?${DIGITS})?|(?:[eE][+-]?${DIGITS}))$`,
)

const STOP_CHARS = new Set([' ', '\t', ',', ']', '}'])

class LineParser {
  constructor(line, pos, lineNo) {
    this.line = line
    this.pos = pos
    this.lineNo = lineNo
  }

  atEnd() {
    return this.pos >= this.line.length
  }

  current() {
    return this.atEnd() ? undefined : this.line[this.pos]
  }

  advance() {
    this.pos++
  }

  skipWs() {
    while (!this.atEnd() && (this.current() === ' ' || this.current() === '\t')) this.advance()
  }

  isEOLorComment() {
    return this.atEnd() || this.current() === '#' || this.current() === ';'
  }

  // Parses one bare word or quoted-string name segment.
  parseNameSegment() {
    if (this.atEnd()) err(this.lineNo, 'expected a name')
    const c = this.current()
    if (c === '"') return this.parseBasicStringContent()
    if (c === "'") return this.parseLiteralStringContent()
    const rest = this.line.slice(this.pos)
    const m = NAME_RE.exec(rest)
    if (!m) err(this.lineNo, 'expected a name')
    this.pos += m[0].length
    return m[0]
  }

  parseDottedName() {
    const segments = [this.parseNameSegment()]
    while (true) {
      const save = this.pos
      this.skipWs()
      if (this.current() === '.') {
        this.advance()
        this.skipWs()
        segments.push(this.parseNameSegment())
      } else {
        this.pos = save
        break
      }
    }
    return segments
  }

  // Consumes the opening quote already checked by the caller? No - caller
  // just peeked; we consume it here.
  parseBasicStringContent() {
    this.advance() // opening quote
    let out = ''
    while (true) {
      if (this.atEnd()) err(this.lineNo, 'unterminated string')
      const c = this.current()
      if (c === '"') {
        this.advance()
        return out
      }
      if (c === '\\') {
        if (this.pos + 1 >= this.line.length) err(this.lineNo, 'unterminated string')
        const next = this.line[this.pos + 1]
        switch (next) {
          case '"':
            out += '"'
            this.pos += 2
            break
          case '\\':
            out += '\\'
            this.pos += 2
            break
          case 'n':
            out += '\n'
            this.pos += 2
            break
          case 't':
            out += '\t'
            this.pos += 2
            break
          case 'r':
            out += '\r'
            this.pos += 2
            break
          case '0':
            out += '\0'
            this.pos += 2
            break
          case 'u': {
            const hex = this.line.slice(this.pos + 2, this.pos + 6)
            if (hex.length === 4 && /^[0-9A-Fa-f]{4}$/.test(hex)) {
              out += String.fromCharCode(parseInt(hex, 16))
              this.pos += 6
            } else {
              err(this.lineNo, `invalid escape \\u`)
            }
            break
          }
          default:
            err(this.lineNo, `invalid escape \\${next}`)
        }
        continue
      }
      out += c
      this.advance()
    }
  }

  parseLiteralStringContent() {
    this.advance() // opening quote
    let out = ''
    while (true) {
      if (this.atEnd()) err(this.lineNo, 'unterminated string')
      const c = this.current()
      if (c === "'") {
        this.advance()
        return out
      }
      out += c
      this.advance()
    }
  }

  captureToken() {
    const start = this.pos
    while (!this.atEnd() && !STOP_CHARS.has(this.current())) this.advance()
    return this.line.slice(start, this.pos)
  }

  parseValue(pathPrefix) {
    this.skipWs()
    if (this.isEOLorComment()) err(this.lineNo, 'expected a value')
    const c = this.current()
    if (c === ',' || c === ']' || c === '}') err(this.lineNo, 'expected a value')
    if (c === '"') return this.parseBasicStringContent()
    if (c === "'") return this.parseLiteralStringContent()
    if (c === '[') return this.parseArray(pathPrefix)
    if (c === '{') return this.parseInlineTable(pathPrefix)
    const token = this.captureToken()
    if (token === 'true') return true
    if (token === 'false') return false
    if (INT_RE.test(token)) return Number(token.replace(/_/g, ''))
    if (FLOAT_RE.test(token)) return new TFloat(parseFloat(token.replace(/_/g, '')))
    err(this.lineNo, `invalid value ${token}`)
  }

  parseArray(pathPrefix) {
    this.advance() // '['
    const arr = []
    this.skipWs()
    if (this.current() === ']') {
      this.advance()
      return arr
    }
    while (true) {
      const v = this.parseValue(pathPrefix)
      arr.push(v)
      this.skipWs()
      if (this.isEOLorComment()) err(this.lineNo, 'unterminated array')
      const c = this.current()
      if (c === ',') {
        this.advance()
        this.skipWs()
        if (this.isEOLorComment()) err(this.lineNo, 'unterminated array')
        if (this.current() === ']') {
          this.advance()
          break
        }
        continue
      } else if (c === ']') {
        this.advance()
        break
      } else {
        err(this.lineNo, 'unterminated array')
      }
    }
    return arr
  }

  parseInlineTable(pathPrefix) {
    this.advance() // '{'
    const obj = newTable()
    this.skipWs()
    if (this.current() === '}') {
      this.advance()
      return obj
    }
    while (true) {
      this.skipWs()
      if (this.isEOLorComment()) err(this.lineNo, 'unterminated inline table')
      const segments = this.parseDottedName()
      this.skipWs()
      if (this.current() !== '=') err(this.lineNo, 'expected = in an inline table')
      this.advance()
      const fullPath = pathPrefix.concat(segments)
      const value = this.parseValue(fullPath)
      assignLeaf(obj, segments, pathPrefix, value, this.lineNo)
      this.skipWs()
      if (this.isEOLorComment()) err(this.lineNo, 'unterminated inline table')
      if (this.current() === ',') {
        this.advance()
        continue
      } else if (this.current() === '}') {
        this.advance()
        break
      } else {
        err(this.lineNo, 'unterminated inline table')
      }
    }
    return obj
  }
}

function walkToParent(container, segments, pathPrefix, lineNo) {
  let cur = container
  const path = pathPrefix.slice()
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    path.push(seg)
    if (!Object.prototype.hasOwnProperty.call(cur, seg)) {
      const t = newTable()
      cur[seg] = t
      cur = t
    } else {
      const existing = cur[seg]
      if (Array.isArray(existing)) {
        if (aotSet.has(existing)) {
          cur = existing[existing.length - 1]
        } else {
          err(lineNo, `${path.join('.')} is not a table`)
        }
      } else if (isTable(existing)) {
        cur = existing
      } else {
        err(lineNo, `${path.join('.')} is not a table`)
      }
    }
  }
  return { container: cur, lastSeg: segments[segments.length - 1], fullPath: path.concat([segments[segments.length - 1]]) }
}

function assignLeaf(container, segments, pathPrefix, value, lineNo) {
  const { container: parent, lastSeg, fullPath } = walkToParent(container, segments, pathPrefix, lineNo)
  if (Object.prototype.hasOwnProperty.call(parent, lastSeg)) {
    err(lineNo, `key ${fullPath.join('.')} is defined twice`)
  }
  parent[lastSeg] = value
}

function applyHeader(state, segments, isArray, lineNo) {
  const { container, lastSeg, fullPath } = walkToParent(state.root, segments, [], lineNo)
  const pathStr = fullPath.join('.')
  if (!isArray) {
    if (!Object.prototype.hasOwnProperty.call(container, lastSeg)) {
      const t = newTable()
      tableMeta.get(t).headerDefined = true
      container[lastSeg] = t
      state.currentTable = t
      state.currentPath = fullPath
    } else {
      const existing = container[lastSeg]
      if (!isTable(existing)) err(lineNo, `${pathStr} is not a table`)
      const meta = tableMeta.get(existing)
      if (meta.headerDefined) err(lineNo, `table ${pathStr} is defined twice`)
      meta.headerDefined = true
      state.currentTable = existing
      state.currentPath = fullPath
    }
  } else {
    if (!Object.prototype.hasOwnProperty.call(container, lastSeg)) {
      const arr = []
      aotSet.add(arr)
      container[lastSeg] = arr
      const t = newTable()
      tableMeta.get(t).headerDefined = true
      arr.push(t)
      state.currentTable = t
      state.currentPath = fullPath
    } else {
      const existing = container[lastSeg]
      if (!(Array.isArray(existing) && aotSet.has(existing))) {
        err(lineNo, `${pathStr} is not an array of tables`)
      }
      const t = newTable()
      tableMeta.get(t).headerDefined = true
      existing.push(t)
      state.currentTable = t
      state.currentPath = fullPath
    }
  }
}

function handleHeaderLine(p, lineNo, state) {
  p.advance() // '['
  let isArray = false
  if (p.current() === '[') {
    isArray = true
    p.advance()
  }
  const segments = p.parseDottedName()
  p.skipWs()
  if (isArray) {
    if (p.current() !== ']') err(lineNo, 'unterminated table header')
    p.advance()
    p.skipWs()
    if (p.current() !== ']') err(lineNo, 'unterminated table header')
    p.advance()
  } else {
    if (p.current() !== ']') err(lineNo, 'unterminated table header')
    p.advance()
  }
  p.skipWs()
  if (!p.isEOLorComment()) err(lineNo, 'trailing text after a table header')
  applyHeader(state, segments, isArray, lineNo)
}

function handleAssignmentLine(p, lineNo, state) {
  const segments = p.parseDottedName()
  p.skipWs()
  if (p.current() !== '=') err(lineNo, 'expected key = value')
  p.advance()
  const fullPath = state.currentPath.concat(segments)
  const value = p.parseValue(fullPath)
  p.skipWs()
  if (!p.isEOLorComment()) err(lineNo, 'trailing text after a value')
  assignLeaf(state.currentTable, segments, state.currentPath, value, lineNo)
}

export function parseDocument(input) {
  const root = newTable()
  const state = { root, currentTable: root, currentPath: [] }

  let lines = input.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()

  for (let idx = 0; idx < lines.length; idx++) {
    const lineNo = idx + 1
    const line = lines[idx]
    let i = 0
    while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
    if (i >= line.length) continue // blank
    const c = line[i]
    if (c === '#' || c === ';') continue // comment-only
    const p = new LineParser(line, i, lineNo)
    if (c === '[') {
      handleHeaderLine(p, lineNo, state)
    } else {
      handleAssignmentLine(p, lineNo, state)
    }
  }

  return root
}
"}

