/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import fs from 'node:fs'
import { parseDocument, ParseError } from './parser.js'
import { printJson, printKeys } from './print.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'json' && mode !== 'keys') {
    fail('usage: cli.js json|keys')
    return
  }

  let input
  try {
    input = fs.readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e instanceof ParseError) {
      fail(`line ${e.line}: ${e.reason}`)
      return
    }
    throw e
  }

  const output = mode === 'json' ? printJson(root) : printKeys(root)
  process.stdout.write(output)
  process.exit(0)
}

main()
"}

